<script setup lang="ts">
import {onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {api} from './api'

const props=defineProps<{shopId:string|null;shops:{id:string;name:string;mode?:string}[];refreshKey?:number}>()
const emit=defineEmits<{changed:[];busy:[value:boolean]}>()
const items=ref<any[]>([]),jobs=ref<any[]>([]),selected=ref(''),busy=ref(false),message=ref(''),failed=ref(false),worker=ref(true)
const editor=ref(false),editing=ref<any>(null),days=ref(7)
const factsConnection=ref(''),factsProducts=ref<any[]>([]),factsProduct=ref(''),factsOpen=ref(false)
const facts=reactive({cost:'',size:'',color:'',material:'',fit:'',season:'',occasion:'',evidence:''})
const form=reactive({name:'',provider:'doudian',mode:'live',shop_id:'',external_id:'',app_key:'',app_secret:'',access_token:'',refresh_token:'',token_expires_in:3600,redirect_uri:'',scopes:'video.list,data.external.item',interval_minutes:60})
const statuses:Record<string,string>={unconfigured:'待填写配置',configured:'待检查凭证',connected:'凭证检查通过',authorization_required:'需要授权',error:'连接异常',disconnected:'已断开',queued:'排队中',running:'同步中',retry_wait:'等待自动重试',succeeded:'同步完成',partial:'部分完成',failed:'同步失败',cancelled:'已取消',available:'已验证可用',blocked:'权限或授权不足'}
const resources:Record<string,string>={products:'商品与SKU',orders:'订单',refunds:'售后退款',videos:'视频列表',video_metrics:'视频基础统计'}
let alive=true
const time=(v:string|null)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚无记录'
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;emit('busy',true);message.value='';failed.value=false;try{await fn()}catch(e){failed.value=true;message.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false;emit('busy',false)}}
async function load(){const result=await api('/platform/connections');if(!alive)return;items.value=result.items;worker.value=result.worker_enabled;if(!items.value.some(x=>x.id===selected.value))selected.value=items.value[0]?.id||'';await loadJobs()}
async function loadJobs(){if(!selected.value){jobs.value=[];return}const id=selected.value;const r=await api(`/platform/connections/${id}/syncs`);if(alive&&selected.value===id)jobs.value=r.items}
function open(row?:any){editing.value=row||null;Object.assign(form,{name:row?.shop_name||'',provider:row?.provider||'doudian',mode:row?.mode||'live',shop_id:'',external_id:row?.external_id||'',app_key:row?.app_key||'',app_secret:'',access_token:'',refresh_token:'',token_expires_in:3600,redirect_uri:row?.options.redirect_uri||'',scopes:row?.options.scopes||'video.list,data.external.item',interval_minutes:row?.interval_minutes||60});editor.value=true}
async function save(){await act(async()=>{const payload={...form,shop_id:form.shop_id||null,app_secret:form.app_secret||null,access_token:form.access_token||null,refresh_token:form.refresh_token||null,...(editing.value?{expected_version:editing.value.version}:{})};const row=await api('/platform/connections'+(editing.value?`/${editing.value.id}`:''),editing.value?'PATCH':'POST',payload);form.app_secret='';form.access_token='';form.refresh_token='';editor.value=false;selected.value=row.id;emit('changed');await load();message.value='配置已保存。正式连接需完成平台授权并通过连接检查，才会同步数据。'})}
async function simulation(){await act(async()=>{const row=await api('/platform/connections','POST',{name:'抖店接口演练',provider:'doudian',mode:'simulation',external_id:`SIM-${Date.now()}`});selected.value=row.id;await api(`/platform/connections/${row.id}/connect`,'POST',{});await api(`/platform/connections/${row.id}/sync`,'POST',{days:7});emit('changed');await load();message.value='演练任务已排队。全程使用本地模拟平台响应，不连接真实店铺。'})}
async function connect(row:any){await act(async()=>{await api(`/platform/connections/${row.id}/connect`,'POST',{});await load();message.value='凭证检查通过。每项数据权限将在实际同步时分别验证。'})}
async function sync(row:any){await act(async()=>{const result=await api(`/platform/connections/${row.id}/sync`,'POST',{days:days.value});selected.value=row.id;await load();message.value=`同步任务已${statuses[result.status]||result.status}，完成后可切换店铺查看数据。`})}
async function schedule(row:any){await act(async()=>{await api(`/platform/connections/${row.id}/schedule`,'PUT',{enabled:!row.enabled,interval_minutes:row.interval_minutes});await load();message.value=row.enabled?'自动同步已暂停。':'自动同步已开启，服务运行期间执行。'})}
async function disconnect(row:any){await act(async()=>{await api(`/platform/connections/${row.id}/disconnect`,'POST',{});await load();message.value='本地同步已断开，已有经营记录保留；如需撤销平台授权，请在平台授权管理中操作。'})}
async function authorize(row:any){await act(async()=>{const r=await api(`/platform/connections/${row.id}/authorize`,'POST',{});const a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';a.click();message.value='已打开抖音授权页面，完成后点击刷新连接。'})}
async function jobAction(job:any,action:string){await act(async()=>{await api(`/platform/syncs/${job.id}/${action}`,'POST',{});await load()})}
function chooseFacts(){const p=factsProducts.value.find(p=>p.sku_id===factsProduct.value);Object.assign(facts,{cost:p?.cost_fen==null?'':(p.cost_fen/100).toFixed(2),size:p?.size||'',color:p?.color||'',material:p?.material||'',fit:p?.fit||'',season:p?.season||'',occasion:p?.occasion||'',evidence:p?.operator_facts_note||''})}
async function openFacts(row:any){await act(async()=>{const r=await api(`/platform/connections/${row.id}/products`);factsConnection.value=row.id;factsProducts.value=r.items;if(!r.items.length){message.value='请先同步商品资料。';return}factsProduct.value=r.items[0].sku_id;chooseFacts();factsOpen.value=true})}
async function saveFacts(){await act(async()=>{if(facts.cost&&!/^\d+(\.\d{1,2})?$/.test(facts.cost))throw new Error('成本请填写最多两位小数的人民币金额');const [whole='0',fraction='']=facts.cost.split('.');const payload={...facts,cost_fen:facts.cost?Number(whole)*100+Number(fraction.padEnd(2,'0')):null,cost:undefined};const result=await api(`/platform/connections/${factsConnection.value}/products/${factsProduct.value}`,'PATCH',payload);const index=factsProducts.value.findIndex(p=>p.sku_id===factsProduct.value);factsProducts.value[index]=result;message.value='已保存商品补充资料，后续同步会保留；可用于商品筛选和脚本事实检查。';factsOpen.value=false})}
watch(()=>props.shopId,()=>{void act(load)})
watch(()=>props.refreshKey,()=>{void act(load)})
onMounted(()=>{void act(load)})
const poll=window.setInterval(()=>{if(alive&&!busy.value&&jobs.value.some(j=>['queued','running','retry_wait'].includes(j.status)))void act(load)},4000)
onUnmounted(()=>{alive=false;window.clearInterval(poll);emit('busy',false)})
</script>

<template>
  <div class="platform-page">
    <section class="panel setup-intro"><span class="eyebrow">OFFICIAL DATA CONNECTION</span><h2>准备好连接真实店铺</h2><p>先配置、再授权、检查连接后同步。现在没有真实数据，也可以完整演练。</p><ol><li>在抖店开放平台创建商家自研应用，并完成店铺授权。</li><li>填写 App Key、App Secret 和店铺 ID，点击“检查连接”。</li><li>点击“立即同步”，确认结果后开启定时同步。</li></ol><p>抖音视频账号需单独授权。这里不收集平台登录密码；凭证只保存在服务端，保存后不回显。</p><div class="controls"><button class="primary" :disabled="busy" @click="open()">新增平台接入</button><button class="secondary" :disabled="busy" @click="simulation">无凭证演练</button><button class="text-button" :disabled="busy" @click="act(load)">刷新连接</button><a href="https://op.jinritemai.com/docs" target="_blank" rel="noopener">抖店官方文档 ↗</a></div></section>
    <p v-if="message" role="status" :class="['notice',{error:failed}]">{{message}}</p>
    <p v-if="!worker" class="notice error">同步后台未启用。请将 PLATFORM_WORKER_ENABLED 设为 true 并重启服务。</p>
    <section v-if="!items.length" class="panel"><h3>尚未添加连接</h3><p>可以先保存空配置，后续补入正式凭证；或者使用演练验证数据进入分析、SOP和商品查询的流程。</p></section>
    <article v-for="row in items" :key="row.id" class="panel connection">
      <header><div><h3>{{row.shop_name}}</h3><p>{{row.provider==='doudian'?'抖店商家自研':'抖音账号数据'}} · {{row.mode==='live'?'正式接入':'模拟接口演练'}} · {{statuses[row.status]||row.status}}</p></div><button class="secondary" :disabled="busy" @click="open(row)">编辑配置</button></header>
      <dl><div><dt>外部账号 / 店铺ID</dt><dd>{{row.external_id||'待填写或授权'}}</dd></div><div><dt>应用凭证</dt><dd>{{row.mode==='simulation'?'模拟凭证，无需填写':`${row.app_key||'Key待填写'} · ${row.has_secret?'Secret已保存':'Secret待填写'}`}}</dd></div><div><dt>凭证有效期</dt><dd>{{time(row.expires_at)}}</dd></div><div><dt>最近同步</dt><dd>{{time(row.last_sync_at)}}</dd></div></dl>
      <p v-if="row.missing.length">待补充：{{row.missing.join('、')}}</p><p v-if="row.error" class="error">{{row.error}}</p>
      <div class="capabilities"><span v-for="resource in row.resources" :key="resource">{{resources[resource]}}：{{statuses[row.capabilities[resource]?.status]||'待同步验证'}}</span></div>
      <div class="controls"><button class="secondary" :disabled="busy" @click="connect(row)">检查连接</button><button v-if="row.provider==='douyin'&&row.mode==='live'" class="secondary" :disabled="busy" @click="authorize(row)">打开账号授权</button><label>同步最近 <select v-model.number="days" :disabled="busy"><option :value="7">7天</option><option :value="30">30天</option><option :value="90">90天</option></select></label><button class="primary" :disabled="busy||row.status!=='connected'" @click="sync(row)">立即同步</button><button class="secondary" :disabled="busy||row.status!=='connected'" @click="schedule(row)">{{row.enabled?'暂停':'开启'}}每{{row.interval_minutes}}分钟同步</button><button class="text-button" :disabled="busy" @click="disconnect(row)">断开同步</button></div>
      <p class="footnote">{{row.mode==='simulation'?'数据明确标记为模拟，不进入正式店铺统计。':'接口实际返回和获批权限决定可用数据。采购成本、访客、完播、商品点击和归因成交缺失时保持未知。'}}首轮历史同步后持续按更新时间增量补拉；同步完成不等于所有指标都已具备。</p>
      <div class="controls"><button class="text-button" :disabled="busy" @click="selected=row.id;act(loadJobs)">查看此连接的同步记录</button>
      <button v-if="row.provider==='doudian'" class="text-button" :disabled="busy" @click="openFacts(row)">补充商品成本与规格</button></div>
    </article>
    <section v-if="selected" class="panel"><h3>同步记录 · {{items.find(x=>x.id===selected)?.shop_name}}</h3><p v-if="!jobs.length">暂无同步任务。</p><article v-for="job in jobs" :key="job.id" class="sync-job"><strong>{{statuses[job.status]||job.status}} · 第{{job.attempts}}次尝试</strong><p>{{time(job.created_at)}} · {{job.id}}</p><p v-if="job.error" class="error">{{job.error}}</p><ul><li v-for="(result,key) in job.result" :key="key">{{resources[String(key)]||key}}：{{statuses[result.status]||result.status}}<span v-if="result.records!=null">，写入/更新 {{result.records}} 条</span><span v-if="result.error">，{{result.error}}</span></li></ul><div class="controls"><button v-if="['failed','partial'].includes(job.status)" class="secondary" :disabled="busy" @click="jobAction(job,'retry')">仅重试未成功资源</button><button v-if="['queued','retry_wait'].includes(job.status)" class="text-button" :disabled="busy" @click="jobAction(job,'cancel')">取消排队</button></div></article></section>
    <div v-if="factsOpen" class="modal-backdrop"><form class="modal platform-form" @submit.prevent="saveFacts"><h2>补充商品事实</h2><p>接口未明确提供的规格保持未知。填写有依据的资料后，后续同步会保留这些补充值。</p><label>商品SKU<select v-model="factsProduct" @change="chooseFacts"><option v-for="p in factsProducts" :key="p.sku_id" :value="p.sku_id">{{p.title}} · {{p.external_sku_id}}</option></select></label><div class="two-columns"><label>采购成本（元，可空）<input v-model="facts.cost" inputmode="decimal"/></label><label>尺码<input v-model="facts.size" maxlength="30"/></label><label>颜色<input v-model="facts.color" maxlength="60"/></label><label>版型<input v-model="facts.fit" maxlength="60"/></label><label>季节<input v-model="facts.season" maxlength="60"/></label><label>场景<input v-model="facts.occasion" maxlength="100"/></label></div><label>面料成分<input v-model="facts.material" maxlength="500"/></label><label>资料依据<textarea v-model="facts.evidence" required minlength="3" maxlength="2000" placeholder="例如供货单、商品标签或供应商规格表"/></label><div class="controls"><button class="primary" :disabled="busy">保存补充资料</button><button class="secondary" type="button" :disabled="busy" @click="factsOpen=false">取消</button></div><p v-if="failed" class="error">{{message}}</p></form></div>
    <div v-if="editor" class="modal-backdrop" @click.self="!busy&&(editor=false)"><form class="modal platform-form" @submit.prevent="save"><h2>{{editing?'编辑接入':'新增接入'}}</h2><label>店铺显示名称<input v-model="form.name" maxlength="80" required/></label><div class="two-columns"><label>平台<select v-model="form.provider" :disabled="!!editing"><option value="doudian">抖店商家自研</option><option value="douyin">抖音视频账号</option></select></label><label>数据环境<select v-model="form.mode" :disabled="!!editing"><option value="live">正式接入</option><option value="simulation">模拟演练</option></select></label></div><label v-if="!editing">关联已有平台店铺（可选）<select v-model="form.shop_id"><option value="">新建独立店铺</option><option v-for="shop in shops.filter(s=>s.mode===form.mode)" :key="shop.id" :value="shop.id">{{shop.name}}</option></select></label><label>{{form.provider==='doudian'?'平台店铺ID':'Open ID（也可通过授权取得）'}}<input v-model="form.external_id" maxlength="120" autocomplete="off"/></label><label>{{form.provider==='doudian'?'App Key':'Client Key'}}<input v-model="form.app_key" maxlength="120" autocomplete="off"/></label><label>{{form.provider==='doudian'?'App Secret':'Client Secret'}}<input v-model="form.app_secret" type="password" autocomplete="new-password" :placeholder="editing?.has_secret?'已保存，留空保留':'后续取得后填写'"/></label><label>自动同步间隔（分钟）<input v-model.number="form.interval_minutes" type="number" min="15" max="1440" required/></label><details v-if="form.provider==='douyin'"><summary>抖音授权或API凭证</summary><label>授权回调地址<input v-model="form.redirect_uri" placeholder="https://你的域名/api/platform/oauth/callback" maxlength="500"/></label><label>应用已获批的权限Scope<input v-model="form.scopes" maxlength="500"/></label><label>Access Token（已有凭证时填写）<input v-model="form.access_token" type="password" autocomplete="new-password"/></label><label>Refresh Token（可选）<input v-model="form.refresh_token" type="password" autocomplete="new-password"/></label><label>本次Token剩余有效秒数<input v-model.number="form.token_expires_in" type="number" min="60" max="31536000"/></label><p>当前适配官方视频列表和近期视频基础统计。若应用使用不同经营授权能力，需按实际获批接口核验，不能仅靠勾选Scope获得权限。</p></details><p>可先保存待配置状态。正式环境不会使用模拟响应补数。</p><div class="controls"><button class="primary" :disabled="busy">保存配置</button><button type="button" class="secondary" :disabled="busy" @click="editor=false">取消</button></div><p v-if="failed" class="error">{{message}}</p></form></div>
  </div>
</template>

<style scoped>
.setup-intro h2{margin:12px 0}.platform-page p,.platform-page li,.platform-page a{font-size:12px;line-height:1.9}.platform-page p,.platform-page dt{color:var(--muted)}.platform-page .panel{margin-bottom:20px}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.controls label{display:flex;gap:6px;align-items:center;font-size:12px}.controls select{padding:7px}.connection header{display:flex;justify-content:space-between;gap:16px}.connection dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:18px 0}.connection dt{font-size:11px}.connection dd{font-size:12px;margin:5px 0;overflow-wrap:anywhere}.capabilities{display:flex;flex-wrap:wrap;gap:8px}.capabilities span{font-size:11px;padding:7px;background:#f0f4ef;border-radius:6px}.notice{padding:14px;background:#eef5eb;border-radius:8px}.platform-page .error{color:#9c432c}.sync-job{border-top:1px solid var(--line);padding:16px 0}.sync-job strong{font-size:13px}.platform-form label{display:flex;flex-direction:column;gap:7px;font-size:12px;margin:14px 0}.platform-form input,.platform-form select{width:100%}.platform-form details{margin:14px 0}.platform-form{max-height:88vh;overflow:auto}@media(max-width:650px){.connection dl{grid-template-columns:1fr}.connection header{flex-wrap:wrap}.platform-page .panel{padding:16px}}
</style>
